<?php $dir = __DIR__."/app/Models"; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir)); foreach($it as $f) { if($f->getExtension() == "php") { $c = file_get_contents($f->getPathname()); if(str_contains($c, "protected \$guarded = []")) echo "Guarded: ".$f->getPathname()."\n"; if(!str_contains($c, "protected \$guarded") && !str_contains($c, "protected \$fillable")) echo "None: ".$f->getPathname()."\n"; } }
